import java.util.*;

final class Driver {
    record Input(String name, int position) {}
    static final class Node {
        String symbol, mark;
        List<Node> children = new ArrayList<>();
        Node(String symbol) {
            this.symbol = symbol;
        }
    }
    record StackEntry(String symbol, Node node) {}
    record Trace(int step, List<String> stack, List<String> input, String action) {}
    record Event(int step, String kind, String symbol, String token, int position) {}
    static final class Result {
        Node root;
        List<Trace> trace = new ArrayList<>();
        List<Integer> leftParse = new ArrayList<>();
        List<Event> errors = new ArrayList<>();
        int predicts, matches, skip, pop, missing, maxStack;
    }
    static Result parse(List<Input> original, GrammarParser.Grammar grammar, FirstFollow.Sets sets,
                        Table.Result table) {
        List<Input> input = new ArrayList<>(original);
        input.add(new Input("$", original.size() + 1));
        Result result = new Result();
        result.root = new Node(grammar.start);
        List<StackEntry> stack = new ArrayList<>();
        stack.add(new StackEntry("$", null));
        stack.add(new StackEntry(grammar.start, result.root));
        int cursor = 0, step = 0;
        while (true) {
            step++;
            StackEntry entry = stack.getLast();
            String top = entry.symbol();
            Input token = input.get(cursor);
            String current = token.name();
            result.maxStack = Math.max(result.maxStack, stack.size());
            List<String> beforeStack = new ArrayList<>(), beforeInput = new ArrayList<>();
            for (StackEntry value : stack)
                beforeStack.add(value.symbol());
            for (int i = cursor; i < input.size(); i++)
                beforeInput.add(input.get(i).name());
            String action;
            boolean terminate = false;
            Event event = null;
            if (top.equals("$") && current.equals("$")) {
                action = "accept";
                terminate = true;
            } else if (top.equals("$")) {
                action = "error: skip " + current;
                event = new Event(step, "skip", top, current, token.position());
                cursor++;
                result.skip++;
            } else if (!GrammarParser.nonterminal(top)) {
                if (top.equals(current)) {
                    action = "match " + current;
                    stack.removeLast();
                    cursor++;
                    result.matches++;
                } else {
                    action = "error: missing " + top;
                    entry.node().mark = "missing";
                    stack.removeLast();
                    result.missing++;
                    event = new Event(step, "missing", top, current, token.position());
                }
            } else if (table.choices.containsKey(new Table.Cell(top, current))) {
                int number = table.choices.get(new Table.Cell(top, current));
                Table.Production production = table.productions.get(number - 1);
                action = "predict " + number + ": " + production.notation();
                result.leftParse.add(number);
                stack.removeLast();
                if (production.rhs.isEmpty())
                    entry.node().children.add(new Node("%empty"));
                else {
                    List<Node> children = new ArrayList<>();
                    for (String symbol : production.rhs)
                        children.add(new Node(symbol));
                    entry.node().children.addAll(children);
                    for (int i = children.size() - 1; i >= 0; i--)
                        stack.add(new StackEntry(children.get(i).symbol, children.get(i)));
                }
                result.predicts++;
            } else if (current.equals("$") || sets.follow.get(top).contains(current)) {
                action = "error: pop " + top;
                entry.node().mark = "error";
                stack.removeLast();
                result.pop++;
                event = new Event(step, "pop", top, current, token.position());
            } else {
                action = "error: skip " + current;
                cursor++;
                result.skip++;
                event = new Event(step, "skip", top, current, token.position());
            }
            result.trace.add(new Trace(step, beforeStack, beforeInput, action));
            if (event != null)
                result.errors.add(event);
            if (terminate)
                return result;
        }
    }
}

import java.util.*;

final class FirstFollow {
    static List<String> terminalOrder(Collection<String> terminals) {
        List<String> result = new ArrayList<>();
        boolean end = false;
        for (String terminal : terminals)
            if (terminal.equals("$"))
                end = true;
            else
                result.add(terminal);
        Collections.sort(result);
        if (end)
            result.add("$");
        return result;
    }
    static Set<String> terminals(GrammarParser.Grammar grammar) {
        Set<String> result = new HashSet<>();
        for (String lhs : grammar.order)
            for (List<String> rhs : grammar.rules.get(lhs))
                for (String symbol : rhs)
                    if (!GrammarParser.nonterminal(symbol))
                        result.add(symbol);
        return result;
    }
    record Sequence(Set<String> first, boolean empty) {}
    static final class Sets {
        Map<String, Boolean> nullable = new HashMap<>();
        Map<String, Set<String>> first = new HashMap<>(), follow = new HashMap<>();
        int nullablePasses, firstPasses, followPasses;
        List<String> terminals;
    }
    static Sequence sequence(List<String> rhs, Sets sets) {
        Set<String> result = new HashSet<>();
        for (String symbol : rhs) {
            if (!GrammarParser.nonterminal(symbol)) {
                result.add(symbol);
                return new Sequence(result, false);
            }
            result.addAll(sets.first.get(symbol));
            if (!sets.nullable.get(symbol))
                return new Sequence(result, false);
        }
        return new Sequence(result, true);
    }
    static Sets analyze(GrammarParser.Grammar grammar) {
        Sets sets = new Sets();
        for (String lhs : grammar.order) {
            sets.nullable.put(lhs, false);
            sets.first.put(lhs, new HashSet<>());
            sets.follow.put(lhs, new HashSet<>());
        }
        sets.follow.get(grammar.start).add("$");
        boolean changed;
        do {
            sets.nullablePasses++;
            changed = false;
            for (String lhs : grammar.order)
                if (!sets.nullable.get(lhs))
                    for (List<String> rhs : grammar.rules.get(lhs)) {
                        boolean empty = true;
                        for (String symbol : rhs)
                            if (!GrammarParser.nonterminal(symbol) || !sets.nullable.get(symbol))
                                empty = false;
                        if (empty) {
                            sets.nullable.put(lhs, true);
                            changed = true;
                            break;
                        }
                    }
        } while (changed);
        do {
            sets.firstPasses++;
            changed = false;
            for (String lhs : grammar.order)
                for (List<String> rhs : grammar.rules.get(lhs))
                    if (sets.first.get(lhs).addAll(sequence(rhs, sets).first()))
                        changed = true;
        } while (changed);
        do {
            sets.followPasses++;
            changed = false;
            for (String lhs : grammar.order)
                for (List<String> rhs : grammar.rules.get(lhs))
                    for (int i = 0; i < rhs.size(); i++) {
                        String symbol = rhs.get(i);
                        if (!GrammarParser.nonterminal(symbol))
                            continue;
                        Sequence suffix = sequence(rhs.subList(i + 1, rhs.size()), sets);
                        Set<String> more = new HashSet<>(suffix.first());
                        if (suffix.empty())
                            more.addAll(sets.follow.get(lhs));
                        if (sets.follow.get(symbol).addAll(more))
                            changed = true;
                    }
        } while (changed);
        sets.terminals = terminalOrder(terminals(grammar));
        return sets;
    }
}

import java.util.*;

final class GrammarParser {
    static final class Grammar {
        List<String> order = new ArrayList<>();
        Map<String, List<List<String>>> rules = new LinkedHashMap<>();
        String start;
        Set<String> declared = new HashSet<>();
        boolean hasDeclaration;
        Map<String, Integer> words = new HashMap<>();
        List<String> diagnostics = new ArrayList<>();
    }
    record Token(String kind, String value, int start, int end) {}
    record Parsed(String kind, String lhs, List<List<String>> alternatives, List<String> words, int error) {}
    static boolean nonterminal(String symbol) {
        return symbol.startsWith("<") && symbol.endsWith(">");
    }
    static boolean letter(char c) {
        return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z';
    }
    static boolean word(char c) {
        return letter(c) || c >= '0' && c <= '9' || c == '_';
    }
    static List<Token> lex(String line) {
        List<Token> tokens = new ArrayList<>();
        int i = 0;
        while (i < line.length()) {
            char c = line.charAt(i);
            if (c == ' ') {
                i++;
                continue;
            }
            if (c == '#')
                break;
            int start = i;
            String kind = "invalid", value = Character.toString(c);
            if (c == '<') {
                int j = i + 1;
                if (j < line.length() && letter(line.charAt(j))) {
                    j++;
                    while (j < line.length() && word(line.charAt(j)))
                        j++;
                    if (j < line.length() && line.charAt(j) == '>') {
                        kind = "nonterminal";
                        i = j + 1;
                        value = line.substring(start, i);
                    }
                }
            } else if (c == '"') {
                int j = i + 1;
                while (j < line.length() && line.charAt(j) != ' ' && line.charAt(j) != '"')
                    j++;
                if (j > i + 1 && j < line.length() && line.charAt(j) == '"') {
                    kind = "terminal";
                    value = line.substring(i + 1, j);
                    i = j + 1;
                }
            } else if (letter(c)) {
                int j = i + 1;
                while (j < line.length() && word(line.charAt(j)))
                    j++;
                kind = "word";
                i = j;
                value = line.substring(start, i);
            } else if (line.startsWith("::=", i)) {
                kind = "definition";
                value = "::=";
                i += 3;
            } else if (c == '|') {
                kind = "separator";
                value = "|";
                i++;
            } else if (c == '%') {
                int j = i + 1;
                while (j < line.length() && letter(line.charAt(j)))
                    j++;
                String directive = line.substring(i + 1, j);
                if (List.of("empty", "start", "token").contains(directive)) {
                    kind = "directive";
                    value = "%" + directive;
                    i = j;
                }
            }
            if (kind.equals("invalid"))
                i = start + 1;
            tokens.add(new Token(kind, value, start + 1, i));
            if (kind.equals("invalid"))
                break;
        }
        return tokens;
    }
    static int error(List<Token> tokens, int cursor) {
        return cursor < tokens.size() ? tokens.get(cursor).start() : tokens.getLast().end() + 1;
    }
    static Parsed bad(List<Token> tokens, int cursor) {
        return new Parsed("", null, null, null, error(tokens, cursor));
    }
    static boolean symbol(Token token) {
        return List.of("nonterminal", "terminal", "word").contains(token.kind());
    }
    static Parsed alternatives(List<Token> tokens, int cursor, String kind, String lhs) {
        List<List<String>> alternatives = new ArrayList<>();
        while (true) {
            if (cursor >= tokens.size())
                return bad(tokens, cursor);
            Token first = tokens.get(cursor);
            List<String> alternative = new ArrayList<>();
            if (first.kind().equals("directive") && first.value().equals("%empty")) {
                cursor++;
                if (cursor < tokens.size() && !tokens.get(cursor).kind().equals("separator"))
                    return bad(tokens, cursor);
            } else if (symbol(first)) {
                while (cursor < tokens.size() && symbol(tokens.get(cursor)))
                    alternative.add(tokens.get(cursor++).value());
            } else
                return bad(tokens, cursor);
            alternatives.add(alternative);
            if (cursor >= tokens.size())
                return new Parsed(kind, lhs, alternatives, null, 0);
            if (!tokens.get(cursor).kind().equals("separator"))
                return bad(tokens, cursor);
            cursor++;
        }
    }
    static Parsed line(List<Token> tokens) {
        if (tokens.isEmpty())
            return new Parsed("blank", null, null, null, 0);
        Token first = tokens.get(0);
        if (first.kind().equals("nonterminal")) {
            if (tokens.size() < 2)
                return bad(tokens, tokens.size());
            if (!tokens.get(1).kind().equals("definition"))
                return bad(tokens, 1);
            return alternatives(tokens, 2, "rule", first.value());
        }
        if (first.kind().equals("separator"))
            return alternatives(tokens, 1, "continuation", null);
        if (first.kind().equals("directive") && first.value().equals("%start")) {
            if (tokens.size() < 2)
                return bad(tokens, tokens.size());
            if (!tokens.get(1).kind().equals("nonterminal"))
                return bad(tokens, 1);
            if (tokens.size() > 2)
                return bad(tokens, 2);
            return new Parsed("start", tokens.get(1).value(), null, null, 0);
        }
        if (first.kind().equals("directive") && first.value().equals("%token")) {
            if (tokens.size() < 2)
                return bad(tokens, tokens.size());
            List<String> words = new ArrayList<>();
            for (int i = 1; i < tokens.size(); i++) {
                if (!tokens.get(i).kind().equals("word"))
                    return bad(tokens, i);
                words.add(tokens.get(i).value());
            }
            return new Parsed("declaration", null, null, words, 0);
        }
        return bad(tokens, 0);
    }
    static String notation(List<String> symbols) {
        return symbols.isEmpty() ? "%empty" : String.join(" ", symbols);
    }
    static String production(String lhs, List<String> rhs) {
        return lhs + " -> " + notation(rhs);
    }
    static Grammar parse(List<String> lines) {
        Grammar grammar = new Grammar();
        String attachment = null;
        for (int i = 0; i < lines.size(); i++) {
            int number = i + 1;
            List<Token> tokens = lex(lines.get(i));
            Parsed parsed = line(tokens);
            if (parsed.error() > 0) {
                grammar.diagnostics.add("line " + number + ": syntax error at column " + parsed.error());
                attachment = null;
                continue;
            }
            if (parsed.kind().equals("blank"))
                continue;
            String lhs = parsed.lhs();
            if (parsed.kind().equals("rule")) {
                attachment = lhs;
                if (!grammar.rules.containsKey(lhs)) {
                    grammar.order.add(lhs);
                    grammar.rules.put(lhs, new ArrayList<>());
                }
            } else if (parsed.kind().equals("continuation")) {
                if (attachment == null) {
                    grammar.diagnostics.add("line " + number + ": continuation without a rule");
                    continue;
                }
                lhs = attachment;
            } else if (parsed.kind().equals("start")) {
                attachment = null;
                if (grammar.start == null)
                    grammar.start = lhs;
                else
                    grammar.diagnostics.add("line " + number + ": duplicate %start");
            } else {
                attachment = null;
                grammar.hasDeclaration = true;
                grammar.declared.addAll(parsed.words());
            }
            if (parsed.kind().equals("rule") || parsed.kind().equals("continuation")) {
                for (Token token : tokens)
                    if (token.kind().equals("word"))
                        grammar.words.putIfAbsent(token.value(), number);
                for (List<String> alternative : parsed.alternatives()) {
                    if (grammar.rules.get(lhs).contains(alternative))
                        grammar.diagnostics.add("line " + number + ": duplicate alternative " +
                                                production(lhs, alternative));
                    else
                        grammar.rules.get(lhs).add(alternative);
                }
            }
        }
        if (grammar.start == null)
            grammar.start = grammar.order.get(0);
        return grammar;
    }
    static Grammar copy(Grammar original) {
        Grammar result = new Grammar();
        result.order.addAll(original.order);
        result.start = original.start;
        for (String lhs : original.order) {
            List<List<String>> alternatives = new ArrayList<>();
            for (List<String> rhs : original.rules.get(lhs))
                alternatives.add(new ArrayList<>(rhs));
            result.rules.put(lhs, alternatives);
        }
        return result;
    }
}

import java.io.IOException;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.math.BigInteger;
import java.util.*;

public final class Main {
    static GrammarParser.Grammar parsed, cleaned, eliminated, factored, grammar;
    static List<String> diagnostics = new ArrayList<>(), eliminationLog, factorLog,
                        unreachableLog = new ArrayList<>();
    static FirstFollow.Sets sets;
    static Table.Result table;
    static int beforeConflicts;
    static Map<String, Metric> lengths = new HashMap<>(), costs = new HashMap<>();
    static Map<String, List<String>> words = new HashMap<>(), leftContext = new HashMap<>(),
                                     rightContext = new HashMap<>();
    record Metric(BigInteger length, int height) implements Comparable<Metric> {
        public int compareTo(Metric m) {
            int c = length.compareTo(m.length());
            return c != 0 ? c : Integer.compare(height, m.height());
        }
    }
    static BigInteger plus(BigInteger a, BigInteger b) {
        return a.add(b);
    }
    static String list(String heading, Collection<?> values) {
        String line = heading;
        for (Object value : values)
            line += " " + value;
        return line;
    }
    static List<String> lines(String name) throws IOException {
        return Files.readAllLines(Path.of("input", name), StandardCharsets.US_ASCII);
    }
    static void write(String name, List<String> lines) throws IOException {
        Files.writeString(Path.of("output", name), String.join("\n", lines) + "\n",
                          StandardCharsets.US_ASCII);
    }
    static Set<String> reachable(GrammarParser.Grammar g) {
        Set<String> seen = new HashSet<>();
        Deque<String> queue = new ArrayDeque<>();
        queue.add(g.start);
        seen.add(g.start);
        while (!queue.isEmpty()) {
            String lhs = queue.removeFirst();
            for (List<String> rhs : g.rules.get(lhs))
                for (String symbol : rhs)
                    if (GrammarParser.nonterminal(symbol) && seen.add(symbol))
                        queue.add(symbol);
        }
        return seen;
    }
    static String firstRemoved(List<String> rhs, Set<String> removed) {
        for (String symbol : rhs)
            if (removed.contains(symbol))
                return symbol;
        return null;
    }
    static void filterAlternatives(GrammarParser.Grammar g, Set<String> removed, String reason) {
        for (String lhs : g.order) {
            List<List<String>> keep = new ArrayList<>();
            for (List<String> rhs : g.rules.get(lhs)) {
                String symbol = firstRemoved(rhs, removed);
                if (symbol == null)
                    keep.add(rhs);
                else
                    diagnostics.add("removed " + GrammarParser.production(lhs, rhs) + " (" + reason + " " +
                                    symbol + ")");
            }
            g.rules.put(lhs, keep);
        }
    }
    static void remove(GrammarParser.Grammar g, Set<String> removed) {
        g.order.removeIf(removed::contains);
        for (String symbol : removed)
            g.rules.remove(symbol);
    }
    static GrammarParser.Grammar clean() {
        GrammarParser.Grammar g = GrammarParser.copy(parsed);
        if (parsed.hasDeclaration)
            for (String word : FirstFollow.terminalOrder(parsed.words.keySet()))
                if (!parsed.declared.contains(word))
                    diagnostics.add("undeclared terminal " + word + " at line " + parsed.words.get(word));
        Set<String> undefined = new HashSet<>();
        for (String lhs : g.order)
            for (List<String> rhs : g.rules.get(lhs))
                for (String symbol : rhs)
                    if (GrammarParser.nonterminal(symbol) && !g.rules.containsKey(symbol))
                        undefined.add(symbol);
        List<String> sorted = new ArrayList<>(undefined);
        sorted.sort((a, b) -> a.substring(1, a.length() - 1).compareTo(b.substring(1, b.length() - 1)));
        for (String symbol : sorted)
            diagnostics.add("undefined nonterminal " + symbol);
        filterAlternatives(g, undefined, "undefined");
        Set<String> productive = new HashSet<>();
        boolean changed;
        do {
            changed = false;
            for (String lhs : g.order)
                if (!productive.contains(lhs))
                    for (List<String> rhs : g.rules.get(lhs)) {
                        boolean valid = true;
                        for (String symbol : rhs)
                            if (GrammarParser.nonterminal(symbol) && !productive.contains(symbol))
                                valid = false;
                        if (valid) {
                            productive.add(lhs);
                            changed = true;
                            break;
                        }
                    }
        } while (changed);
        Set<String> removed = new HashSet<>();
        for (String lhs : g.order)
            if (!productive.contains(lhs)) {
                removed.add(lhs);
                diagnostics.add("unproductive nonterminal " + lhs);
            }
        remove(g, removed);
        filterAlternatives(g, removed, "unproductive");
        Set<String> reachable = reachable(g);
        removed = new HashSet<>();
        for (String lhs : g.order)
            if (!reachable.contains(lhs)) {
                removed.add(lhs);
                diagnostics.add("unreachable nonterminal " + lhs);
            }
        remove(g, removed);
        return g;
    }
    static void leftRecursion() {
        for (String origin : cleaned.order) {
            Deque<String> queue = new ArrayDeque<>();
            Map<String, String> parent = new HashMap<>();
            Set<String> seen = new HashSet<>();
            queue.add(origin);
            seen.add(origin);
            String last = null;
            while (!queue.isEmpty() && last == null) {
                String current = queue.removeFirst();
                for (List<String> rhs : cleaned.rules.get(current)) {
                    if (rhs.isEmpty())
                        continue;
                    String first = rhs.get(0);
                    if (first.equals(origin)) {
                        last = current;
                        break;
                    }
                    if (GrammarParser.nonterminal(first) && seen.add(first)) {
                        parent.put(first, current);
                        queue.add(first);
                    }
                }
            }
            if (last != null) {
                List<String> path = new ArrayList<>();
                for (String current = last; !current.equals(origin); current = parent.get(current))
                    path.add(current);
                Collections.reverse(path);
                path.add(0, origin);
                path.add(origin);
                diagnostics.add("left recursion: " + String.join(" -> ", path));
            }
        }
    }
    static void prepare() {
        diagnostics.addAll(parsed.diagnostics);
        cleaned = clean();
        leftRecursion();
        FirstFollow.Sets before = FirstFollow.analyze(cleaned);
        beforeConflicts = Table.build(cleaned, before).conflicts.size();
        Transform.Result elimination = Transform.eliminate(cleaned);
        eliminated = elimination.grammar();
        eliminationLog = elimination.log();
        Transform.Result factoring = Transform.factor(eliminated);
        factored = factoring.grammar();
        factorLog = factoring.log();
        grammar = GrammarParser.copy(factored);
        Set<String> reachable = reachable(grammar), removed = new HashSet<>();
        for (String lhs : grammar.order)
            if (!reachable.contains(lhs)) {
                removed.add(lhs);
                unreachableLog.add("remove unreachable " + lhs);
                diagnostics.add("unreachable after transformation " + lhs);
            }
        remove(grammar, removed);
        sets = FirstFollow.analyze(grammar);
        table = Table.build(grammar, sets);
        if (parsed.hasDeclaration) {
            Set<String> unused = new HashSet<>(parsed.declared);
            unused.removeAll(sets.terminals);
            for (String terminal : FirstFollow.terminalOrder(unused))
                diagnostics.add("unused token " + terminal);
        }
        shortest();
        contexts();
    }
    static Metric metric(List<String> rhs) {
        BigInteger length = BigInteger.ZERO;
        int height = 1;
        for (String symbol : rhs)
            if (GrammarParser.nonterminal(symbol)) {
                Metric child = lengths.get(symbol);
                if (child == null)
                    return null;
                length = plus(length, child.length());
                height = Math.max(height, child.height() + 1);
            } else
                length = plus(length, BigInteger.ONE);
        return new Metric(length, height);
    }
    static void shortest() {
        boolean changed;
        do {
            changed = false;
            for (String lhs : grammar.order)
                for (List<String> rhs : grammar.rules.get(lhs)) {
                    Metric candidate = metric(rhs), old = lengths.get(lhs);
                    if (candidate != null && (old == null || candidate.compareTo(old) < 0)) {
                        lengths.put(lhs, candidate);
                        changed = true;
                    }
                }
        } while (changed);
        for (String lhs : grammar.order)
            word(lhs);
    }
    static List<String> word(String lhs) {
        if (words.containsKey(lhs))
            return words.get(lhs);
        for (List<String> rhs : grammar.rules.get(lhs))
            if (metric(rhs).equals(lengths.get(lhs))) {
                List<String> result = sentence(rhs);
                words.put(lhs, result);
                return result;
            }
        throw new IllegalStateException();
    }
    static List<String> sentence(List<String> symbols) {
        List<String> result = new ArrayList<>();
        for (String symbol : symbols)
            if (GrammarParser.nonterminal(symbol))
                result.addAll(word(symbol));
            else
                result.add(symbol);
        return result;
    }
    static Metric contextMetric(Table.Production production, int occurrence) {
        Metric parent = costs.get(production.lhs);
        if (parent == null)
            return null;
        BigInteger length = parent.length();
        for (int i = 0; i < production.rhs.size(); i++)
            if (i != occurrence) {
                String symbol = production.rhs.get(i);
                length = plus(length, GrammarParser.nonterminal(symbol) ? lengths.get(symbol).length()
                                                                        : BigInteger.ONE);
            }
        return new Metric(length, parent.height() + 1);
    }
    static void contexts() {
        costs.put(grammar.start, new Metric(BigInteger.ZERO, 0));
        boolean changed;
        do {
            changed = false;
            for (Table.Production production : table.productions)
                for (int i = 0; i < production.rhs.size(); i++) {
                    String symbol = production.rhs.get(i);
                    if (!GrammarParser.nonterminal(symbol) || symbol.equals(grammar.start))
                        continue;
                    Metric candidate = contextMetric(production, i), old = costs.get(symbol);
                    if (candidate != null && (old == null || candidate.compareTo(old) < 0)) {
                        costs.put(symbol, candidate);
                        changed = true;
                    }
                }
        } while (changed);
        leftContext.put(grammar.start, new ArrayList<>());
        rightContext.put(grammar.start, new ArrayList<>());
        for (String lhs : grammar.order)
            context(lhs);
    }
    static void context(String lhs) {
        if (leftContext.containsKey(lhs))
            return;
        for (Table.Production production : table.productions)
            for (int i = 0; i < production.rhs.size(); i++)
                if (production.rhs.get(i).equals(lhs) && contextMetric(production, i) != null &&
                    contextMetric(production, i).equals(costs.get(lhs))) {
                    context(production.lhs);
                    List<String> left = new ArrayList<>(leftContext.get(production.lhs));
                    left.addAll(sentence(production.rhs.subList(0, i)));
                    List<String> right = sentence(production.rhs.subList(i + 1, production.rhs.size()));
                    right.addAll(rightContext.get(production.lhs));
                    leftContext.put(lhs, left);
                    rightContext.put(lhs, right);
                    return;
                }
    }
    static List<String> example(Table.Production production) {
        List<String> result = new ArrayList<>(leftContext.get(production.lhs));
        result.addAll(sentence(production.rhs));
        result.addAll(rightContext.get(production.lhs));
        return result;
    }
    static String summary(GrammarParser.Grammar g) {
        int productions = 0, empty = 0, unit = 0;
        for (String lhs : g.order)
            for (List<String> rhs : g.rules.get(lhs)) {
                productions++;
                if (rhs.isEmpty())
                    empty++;
                if (rhs.size() == 1 && GrammarParser.nonterminal(rhs.get(0)))
                    unit++;
            }
        return "start=" + g.start + " nonterminals=" + g.order.size() +
            " terminals=" + FirstFollow.terminals(g).size() + " productions=" + productions +
            " empty=" + empty + " unit=" + unit;
    }
    static List<String> listing(GrammarParser.Grammar g, boolean numbered) {
        List<String> result = new ArrayList<>();
        int count = 0;
        for (String lhs : g.order)
            count += g.rules.get(lhs).size();
        int width = Integer.toString(count).length(), number = 0;
        for (String lhs : g.order)
            for (int i = 0; i < g.rules.get(lhs).size(); i++) {
                number++;
                String line = (i == 0 ? lhs + " -> " : " ".repeat(lhs.length()) + " | ") +
                              GrammarParser.notation(g.rules.get(lhs).get(i));
                if (numbered)
                    line = " ".repeat(width - Integer.toString(number).length()) + number + "  " + line;
                result.add(line);
            }
        return result;
    }
    static void stage(List<String> out, String heading, List<String> log, GrammarParser.Grammar g,
                      boolean numbered) {
        out.add(heading);
        if (log != null)
            out.addAll(log.isEmpty() ? List.of("none") : log);
        out.add(summary(g));
        out.addAll(listing(g, numbered));
        out.add("");
    }
